function updateSteps(steps, progress) {
	const { command, phase } = progress;
	const last = steps.at(-1);
	if (phase === "proposed" && command) {
		const step = {
			step: progress.step,
			command,
			status: "proposed",
			lines: [],
			...progress.message ? { note: progress.message } : {}
		};
		if (last && last.step === progress.step && last.command === command) return [...steps.slice(0, -1), {
			...last,
			status: "proposed",
			note: progress.message
		}];
		return [...steps, step].slice(-60);
	}
	if (phase === "running" && command) {
		if (last && last.step === progress.step && last.command === command) return [...steps.slice(0, -1), {
			...last,
			status: "running"
		}];
		return [...steps, {
			step: progress.step,
			command,
			status: "running",
			lines: []
		}].slice(-60);
	}
	if (phase === "thinking" && last) {
		if (last.status === "running") return [...steps.slice(0, -1), {
			...last,
			status: "done"
		}];
		if (last.status === "proposed") return [...steps.slice(0, -1), {
			...last,
			status: "skipped"
		}];
	}
	if ((phase === "finished" || phase === "stopped") && last?.status === "running") return [...steps.slice(0, -1), {
		...last,
		status: "done"
	}];
	return steps;
}
