	const minutes = Math.floor(Math.max(0, now - startedAtUnixMs) / 6e4);
	if (minutes < 1) return "less than a minute";
	const days = Math.floor(minutes / 1440);
	const hours = Math.floor(minutes % 1440 / 60);
	const rest = minutes % 60;
